CREATE TRIGGER task_messages_ad AFTER DELETE ON task_messages BEGIN
          INSERT INTO task_messages_fts(task_messages_fts, rowid, content) VALUES('delete', old.id, old.content);
        END;

CREATE TRIGGER task_messages_ai AFTER INSERT ON task_messages BEGIN
          INSERT INTO task_messages_fts(rowid, content) VALUES (new.id, new.content);
        END;

CREATE TRIGGER task_messages_au AFTER UPDATE ON task_messages BEGIN
          INSERT INTO task_messages_fts(task_messages_fts, rowid, content) VALUES('delete', old.id, old.content);
          INSERT INTO task_messages_fts(rowid, content) VALUES (new.id, new.content);
        END;

COMMIT;
